const menuResponse = $('Load menus and prices').first().json;
const roomTypeResponse = $('Load room types').first().json;
const roomTypes = Array.isArray(roomTypeResponse.data) ? roomTypeResponse.data.filter((room) => room.isActive !== false).map(({ _id, name, baseRate, totalRooms, maxGuestsPerRoom, description, amenities }) => ({ roomTypeId: _id, name, nightlyRate: baseRate, totalRooms, maxGuestsPerRoom, description, amenities })) : [];
const menus = Array.isArray(menuResponse.data) ? menuResponse.data : [];
const conciseMenus = menus.filter((menu) => menu.isActive !== false).map((menu) => ({
  category: menu.category, title: menu.title, subtitle: menu.subtitle, badge: menu.badge, closingLine: menu.closingLine,
  price: menu.price, priceNote: menu.priceNote, menuTimeSlots: menu.menuTimeSlots || [], menuSections: menu.menuSections || [], roomCheckInTime: menu.roomCheckInTime || "", roomCheckOutTime: menu.roomCheckOutTime || "", roomStayDurationHours: menu.roomStayDurationHours || null, hotelInfo: menu.hotelInfo || {},
  description: menu.description, dishes: menu.dishes || [], weddingPackages: (menu.weddingPackages || []).filter((item) => item.isActive !== false), grandestOffer: menu.grandestOffer?.isActive === false ? null : (menu.grandestOffer || null), corporatePackages: (menu.corporatePackages || []).filter((item) => item.isActive !== false), corporateMeals: menu.corporateMeals || [], corporateMenuPreferences: menu.corporateMenuPreferences || [], corporateTaxPercent: menu.corporateTaxPercent, weddingTaxPercent: menu.weddingTaxPercent,
  weddingVenues: menu.weddingVenues || [], weddingSaladOptions: menu.weddingSaladOptions || [], weddingDessertOptions: menu.weddingDessertOptions || [], extraPrices: menu.extraPrices || [],
  media: { imageUrls: menu.media?.imageUrls || [], pdfUrls: menu.media?.pdfUrls || [], videoUrl: menu.media?.videoUrl || "", voiceNoteUrl: menu.media?.voiceNoteUrl || "" },
  activeOffers: (menu.activeOffers || []).map(({ title, description, discountText }) => ({ title, description, discountText })),
}));
const closureResponse = $input.first().json;
const closureData = closureResponse.data || {};
const closures = Array.isArray(closureData.closures) ? closureData.closures : [];
const closureContext = JSON.stringify({
  currentDateInPakistan: closureData.today || 'Unknown',
  priorityInstruction: 'Check these closures before greeting or replying about availability/booking. If today is closed, tell the customer the exact reason immediately. Never promise or create a booking on a listed closed date.',
  closures: closures.map(({ date, reason }) => ({ date, reason })),
});
const source = $('Final customer message').first().json;
return [{ json: { ...source, menuContext: JSON.stringify(conciseMenus), roomTypesContext: JSON.stringify(roomTypes), closureContext } }];

// Safety net for the AI's plain-text answers.
// The AI must never tell a customer that a booking or payment is confirmed unless the CRM says so.
// If it does, the answer is replaced with a truthful one. JSON actions, tags and hand-offs pass through untouched.
const input = $input.first().json;
const raw = String(input.output || '');
const text = raw.trim();

if (!text || text.startsWith('{') || text.includes('***') || /"action"\s*:/.test(text)) {
  return [{ json: { ...input, output: raw, guarded: false } }];
}

let ctx = {};
try { ctx = $('Load customer bookings and payments').first().json.data || {}; } catch (error) { ctx = {}; }
const records = [...(ctx.bookings || []), ...(ctx.eventBookings || [])];
const hasRecord = records.length > 0;
const anyConfirmed = records.some((b) => /confirm|checked_in|completed/i.test(String(b.status || '')) && !/pending/i.test(String(b.status || '')));
const anyPaymentVerified = records.some((b) => b.paymentVerified === true);
const proofOnFile = records.some((b) => b.paymentProofOnFile === true);

// Customer's language, same rule the rest of the workflow uses.
let source = '';
try { source = String($('Final customer message').first().json.userMessage || ''); } catch (error) { source = ''; }
const isUrdu = [...source].some((character) => { const code = character.codePointAt(0); return code >= 1536 && code <= 1791; });
const isRoman = /\b(hai|hain|kya|kar|karo|chahiye|mujhe|aap|apko|aapki|aapka|mein|main|nahi|bhi|ka|ki|ke|ko|se|mera|meri|bata|batao|bato|ji|jee|g|bhej|karein|raha|rahi|ho|gayi|gaya)\b/i.test(source);
const language = isUrdu ? 'ur' : isRoman ? 'roman' : 'en';

// A sentence that asks something or talks about the future is not a claim.
const isQuestionOrFuture = (s) => /\?|\u061F|\b(kar\s*d[ou]n|karun|karenge|karega|karegi|karunga|chahte|chahenge|agar|jab\s+tak|once|after|will|would|please|if|jayegi|jayega|hogi|hoga|ho\s*jaye|ho\s*jaaye|hone\s*(par|ke))\b/i.test(s);
const paidClaim = /(payment|advance|\u0627\u062F\u0627\u0626\u06CC\u06AF\u06CC)[^.!\n]{0,60}(received|confirmed?|verified|mil\s*(gayi|gaya|chuki)|receive\s*ho|ho\s*(gayi|gaya|chuki)|\u0645\u0644\s*\u06AF\u0626\u06CC|\u06C1\u0648\s*\u06AF\u0626\u06CC)/i;
const confirmedClaim = /(booking|reservation|\u0628\u06A9\u0646\u06AF)[^.!\n]{0,60}(confirmed|confirm\s*(ho\s*(chuki|chuka|gayi|gaya|gai)|hai|kar\s*di|kar\s*diya)|\u06A9\u0646\u0641\u0631\u0645\s*\u06C1\u0648\s*(\u06AF\u0626\u06CC|\u0686\u06A9\u06CC))/i;
const savedClaim = /(booking|\u0628\u06A9\u0646\u06AF)[^.!\n]{0,60}(save\s*ho|saved|create\s*ho|created)/i;

const sentences = text.split(/(?<=[.!?\u06D4\n])\s+/).filter(Boolean);
const claims = (regex) => sentences.some((sentence) => !isQuestionOrFuture(sentence) && regex.test(sentence));

const wrongPaid = claims(paidClaim) && !anyPaymentVerified;
const wrongConfirmed = claims(confirmedClaim) && !anyConfirmed;
const wrongSaved = claims(savedClaim) && !hasRecord;
const noProofClaim = /(?:\b(?:abhi\s+tak|abhi\s+bhi)\b[^.!?\n]{0,80}\b(?:payment\s+)?(?:proof|screenshot|screen\s*shot|receipt)\b[^.!?\n]{0,40}\b(?:nahi|nahin|nhi)\s+(?:mila|mili|mil|aaya|aya|aayi|ayi|receive\s+nahi\s+hua)\b|\b(?:we|i)\s+(?:have\s+not|haven't|did\s+not|didn't)\s+(?:yet\s+)?received\b[^.!?\n]{0,60}\b(?:payment\s+)?(?:proof|screenshot|screen\s*shot|receipt)\b|\b(?:cannot|can't|can\s+not)\s+see\b[^.!?\n]{0,60}\b(?:payment\s+)?(?:proof|screenshot|screen\s*shot|receipt)\b|\b(?:payment\s+)?(?:proof|screenshot|screen\s*shot|receipt)\b[^.!?\n]{0,40}\b(?:not received|not visible|not linked|hasn't arrived|has not arrived)\b|(?:\u0627\u0628\u06be\u06cc\s+\u062a\u06a9|\u0627\u0628\u06be\u06cc\s+\u0628\u06be\u06cc).{0,50}(?:\u0627\u0633\u06a9\u0631\u06cc\u0646\s+\u0634\u0627\u0679|\u062b\u0628\u0648\u062a|\u0631\u0633\u06cc\u062f).{0,30}(?:\u0646\u06c1\u06cc\u06ba\s+\u0645\u0644\u0627|\u0646\u06c1\u06cc\u06ba\s+\u0645\u0644\u06cc|\u0645\u0648\u0635\u0648\u0644\s+\u0646\u06c1\u06cc\u06ba|\u0646\u06c1\u06cc\u06ba\s+\u0622\u06cc\u0627|\u0646\u06c1\u06cc\u06ba\s+\u0622\u0626\u06cc))/i;
const wrongNoProof = claims(noProofClaim) && proofOnFile;

if (!wrongPaid && !wrongConfirmed && !wrongSaved && !wrongNoProof) {
  return [{ json: { ...input, output: raw, guarded: false } }];
}

const say = {
  proofReceived: {
    en: 'Your payment proof is received and our team is verifying it. Please wait a little, you will get the confirmation here as soon as it is verified. 🙏',
    roman: 'Aapka payment proof mil gaya hai aur hamari team verify kar rahi hai. Thora wait karein, verify hote hi yahin confirmation mil jayegi. 🙏',
    ur: 'آپ کا ادائیگی کا ثبوت مل گیا ہے اور ہماری ٹیم تصدیق کر رہی ہے۔ براہِ کرم تھوڑا انتظار کریں، تصدیق ہوتے ہی یہیں کنفرمیشن مل جائے گی۔ 🙏',
  },
  needProof: {
    en: 'We have not received your payment proof yet. Once you have paid the advance, please send the screenshot here and our team will verify it. 🙏',
    roman: 'Abhi tak aapka payment proof nahi mila. Advance payment karne ke baad please screenshot yahin bhej dein, hamari team verify kar degi. 🙏',
    ur: 'ابھی تک آپ کا ادائیگی کا ثبوت نہیں ملا۔ ایڈوانس ادا کرنے کے بعد براہِ کرم اسکرین شاٹ یہیں بھیج دیں، ہماری ٹیم تصدیق کر دے گی۔ 🙏',
  },
  pending: {
    en: 'Your booking is saved and still *pending*. It will be confirmed as soon as our team verifies your advance payment. 🙏',
    roman: 'Aapki booking save hai aur abhi *pending* hai. Advance payment verify hote hi hamari team usay confirm kar degi. 🙏',
    ur: 'آپ کی بکنگ محفوظ ہے اور ابھی *پینڈنگ* ہے۔ ایڈوانس کی تصدیق ہوتے ہی ہماری ٹیم اسے کنفرم کر دے گی۔ 🙏',
  },
  noRecord: {
    en: 'Your booking is not saved yet. Please confirm the date, time and number of guests and I will save it for you.',
    roman: 'Aapki booking abhi save nahi hui. Date, time aur kitne log hain confirm kar dein, main save kar deta hoon.',
    ur: 'آپ کی بکنگ ابھی محفوظ نہیں ہوئی۔ براہِ کرم تاریخ، وقت اور افراد کی تعداد کنفرم کر دیں، میں اسے محفوظ کر دیتا ہوں۔',
  },
};

let reply;
if (!hasRecord) reply = say.noRecord[language];
else if (proofOnFile) reply = say.proofReceived[language];
else if (wrongPaid) reply = say.needProof[language];
else reply = say.pending[language];

return [{ json: { ...input, output: reply, guarded: true, originalOutput: raw } }];

