 const noAdvance = language === 'ur' ? 'اس بکنگ کے لیے ایڈوانس درکار نہیں۔ آپ کی بکنگ سٹاف کی تصدیق تک زیرِ التوا رہےگی۔' : language === 'roman' ? 'Is booking ke liye advance required nahi hai. Booking staff ki confirmation tak pending rahegi.' : 'No advance payment is required for this booking. It remains pending until staff confirms it.';
 return labels.greeting + ' ' + b.customerName + ',

